EX = dict(id="nism-viii", series="VIII", code="NISM Series VIII", short="Equity Derivatives", title="Equity Derivatives",
 track="nism-deriv", tag="VIII", level="practitioner",
 blurb="Futures and options on shares and indices: contracts, pricing, payoffs, strategies, clearing, margins and the rules.",
 intro="NISM Series VIII is the mandatory certification for professionals dealing in equity derivatives on Indian exchanges, such as dealers, sales staff, advisers and compliance officers. Half the marks come from futures and options mechanics, which this guide treats with worked numbers.",
 who="Dealers, sales traders, relationship managers, advisers, back-office and compliance staff in broking and banks, and active traders who want a rigorous grounding in futures and options.",
 qs=100, mins=120, **{"pass": 60}, pass_=60, neg="25% of marks", marks=100, days=28,
 glance=[["Format", "Computer-based, multiple-choice questions"], ["Questions and marks", "100 questions, 1 mark each, 100 marks"], ["Duration", "2 hours"], ["Passing score", "60 marks (60%)"], ["Negative marking", "25% of a question's marks, so 0.25 per wrong answer"], ["Certificate validity", "Three years; renew through NISM"], ["Where it leads", "Required to deal in equity derivatives as a registered professional"]],
 checklist=["Redo every payoff calculation on paper: long and short futures, long and short call and put.", "Memorise break-even formulas and maximum profit and loss for each strategy.", "Revise delta, gamma, theta, vega and rho in one line each.", "Re-read units 3 and 4 (50% of marks).", "Take Mock 5 under timed conditions and apply negative marking."],
 tips=["Negative marking is 0.25 per wrong answer. Skip a question only if you have no idea; guessing between two options is worth it.", "Do payoff questions with a quick diagram: it prevents sign errors.", "Read for 'long' or 'short' and 'buyer' or 'seller' before calculating.", "Never forget lot size when asked for a rupee amount.", "Regulatory questions are about exact terms; learn the names of the committees and acts."],
 sheet=[("Option payoffs at expiry (per unit)", [["Position", "Payoff", "Break-even", "Max loss", "Max profit"], ["Long call", "max(S − K, 0) − premium", "K + premium", "Premium", "Unlimited"], ["Short call", "premium − max(S − K, 0)", "K + premium", "Unlimited", "Premium"], ["Long put", "max(K − S, 0) − premium", "K − premium", "Premium", "K − premium"], ["Short put", "premium − max(K − S, 0)", "K − premium", "K − premium", "Premium"]]),
        ("Greeks in one line", [["Greek", "Measures"], ["Delta", "Change in option price for a ₹1 move in the underlying"], ["Gamma", "Change in delta for a ₹1 move in the underlying"], ["Theta", "Loss of option value per day from time passing"], ["Vega", "Change in option price for a 1% move in volatility"], ["Rho", "Change in option price for a 1% move in the interest rate"]])],
 units=[
 dict(n=1, title="Basics of derivatives", w=8,
  overview="A derivative gets its value from something else: a share, an index, a currency or a commodity. This unit teaches the language, the purposes of derivatives and the differences between types.",
  focus=["Forwards versus futures.", "Hedgers, speculators and arbitrageurs.", "Exchange-traded versus over-the-counter."],
  visuals=[("table", "Forward versus futures", [["", "Forward", "Futures"], ["Trading", "Over the counter", "Exchange"], ["Terms", "Customised", "Standardised"], ["Counterparty risk", "Yes", "Guaranteed by clearing corporation"], ["Settlement", "At maturity", "Daily mark-to-market"]], [120, 175, 175])],
  facts=[("Derivative","A derivative is a financial contract whose value depends on, or is derived from, an underlying asset or reference rate such as a share, index, currency or commodity.","A contract's value moves with the price of a stock index.","A derivative is a share issued by a company."),
   ("Underlying","The underlying is the asset or index on which a derivative contract is based.","A futures contract is based on the Nifty 50, which is its reference.","The underlying is the premium paid on an option."),
   ("Forward contract","A forward contract is a private agreement to buy or sell an asset at a fixed price on a future date. It is customised and traded over the counter, with counterparty risk.","Two parties agree privately to exchange an asset at a fixed price in three months.","A forward contract is standardised and traded on exchanges."),
   ("Futures contract","A futures contract is a standardised agreement traded on an exchange to buy or sell an underlying at a fixed price on a future date, with the clearing corporation guaranteeing performance.","An exchange-traded contract in which both parties must settle at expiry.","A futures contract carries no obligation for either party."),
   ("Hedger","A hedger uses derivatives to reduce an existing price risk rather than to profit from price moves.","A fund manager takes an opposite position to protect a stock portfolio from a fall.","A hedger aims to maximise profit from price moves."),
   ("Speculator","A speculator takes positions in derivatives to profit from expected price changes and accepts the risk.","A trader buys index futures expecting a sharp rise.","A speculator has no exposure to the price risk."),
   ("Arbitrageur","An arbitrageur exploits price differences between related markets to earn a low-risk profit.","A trader buys in the cash market and sells in the futures market to lock in a price gap.","An arbitrageur needs to predict the market's direction."),
   ("Exchange-traded derivative","Exchange-traded derivatives have standardised terms, are cleared by a clearing corporation and carry lower counterparty risk.","A contract with a fixed lot size, expiry and daily settlement.","Exchange-traded derivatives are customised for each buyer."),
   ("Over-the-counter derivative","OTC derivatives are privately negotiated and tailor-made but carry higher counterparty and liquidity risk.","Two institutions agree bespoke terms without an exchange.","OTC derivatives are guaranteed by a clearing corporation."),
   ("Swap","A swap is an agreement to exchange cash flows over a period, such as fixed for floating interest payments.","Two parties agree to exchange a fixed rate payment for a floating one.","A swap is an exchange-traded futures contract."),
   ("Leverage","Leverage in derivatives means controlling a large exposure with a small margin, magnifying both gains and losses.","A trader controls a ₹10 lakh position with ₹1.5 lakh margin.","Leverage reduces the risk of losses."),
   ("Price discovery","Derivatives markets help in price discovery by reflecting market expectations about future prices of the underlying.","Futures prices show where the market expects the index to be next month.","Derivatives play no role in price discovery.")]),
 dict(n=2, title="Understanding index", w=2,
  overview="Index derivatives are based on stock indices. A short unit on how an index is built.",
  focus=["Market capitalisation weighting and free float.", "Sensex and Nifty 50."],
  facts=[("Stock index","A stock index is a number measuring the combined price performance of a basket of stocks, used as a market barometer and as the underlying of index derivatives.","A single number tracks how 50 large companies are performing together.","An index measures the price of only one stock."),
   ("Free-float weighting","Free-float market capitalisation weighting weights each stock by the value of shares available for public trading, so promoter holdings are excluded.","A company with a large promoter holding gets a smaller weight in the index.","Free-float weighting counts all issued shares."),
   ("Base value","An index starts at a base value on a base date; the Nifty 50 base is 1000 and the Sensex base is 100, and later values are relative to them.","An index set at 1000 on its base date rises to 2000, doubling in value.","Every index starts at zero."),
   ("Index rebalancing","Index constituents are reviewed periodically and stocks replaced when they no longer meet criteria on market cap, liquidity and free float.","An exchange replaces a stock that no longer qualifies for the index.","Index constituents never change."),
   ("Beta of a portfolio","Beta measures the sensitivity of a portfolio to market moves; a beta of 1.2 means it is expected to move 20% more than the index.","A portfolio typically rises 12% when the index rises 10%.","Beta measures the dividend of a stock.")]),
 dict(n=3, title="Introduction to forwards and futures", w=25,
  overview="The heaviest unit in the exam. Contract specifications, pricing, payoffs, basis, margins and hedging with index futures.",
  focus=["Payoffs of long and short futures.", "Cost of carry pricing.", "Basis, contango and backwardation.", "Hedging with index futures."],
  visuals=[("formula", "Cost of carry", "Futures price = Spot price × (1 + r)^T, adjusted for dividends: F = S × e^((r − d) × T)"), ("formula", "Hedge ratio", "Number of contracts = Beta × Portfolio value ÷ (Futures price × lot size)"), ("table", "Futures payoff per unit", [["Position", "Profit or loss"], ["Long futures", "Spot at expiry − entry price"], ["Short futures", "Entry price − spot at expiry"]], [200, 270])],
  facts=[("Long futures position","A long futures position buys the contract and gains when the price rises above the entry price and loses when it falls.","A trader buys an index future at 24,000 and it moves to 24,100.","A long futures position gains when the price falls."),
   ("Short futures position","A short position sells the contract and gains when the price falls below the entry price and loses when it rises.","A trader sells a future at 24,000 and it closes at 23,900.","A short futures position loses when the price falls."),
   ("Contract specification","An exchange fixes the underlying, lot size, tick size, expiry cycle and settlement method for each derivatives contract.","The exchange standardises everything except the price.","Traders choose the lot size and expiry date themselves."),
   ("Tick size","The tick size is the minimum price movement allowed for a contract, such as ₹0.05 for futures on equity.","A price can change only in steps of five paise.","Tick size is the lot size of the contract."),
   ("Contract value","Contract value equals futures price multiplied by the lot size and shows the exposure in rupees.","A future at ₹2,000 with a lot of 500 has an exposure of ₹10 lakh.","Contract value equals the margin."),
   ("Expiry cycle","Index and stock futures have near-month, next-month and far-month contracts, and a contract expires on the day set by the exchange; on expiry it is cash settled.","Three monthly contracts are available at any time.","Futures contracts have a ten-year expiry cycle."),
   ("Open interest","Open interest is the total number of outstanding contracts not yet squared off or settled, showing how many positions remain open.","A count of all contracts still open at the end of the day.","Open interest is the number of contracts traded in a day."),
   ("Cost of carry","The cost of carry is the cost of holding the underlying until expiry, mainly financing cost less any income such as dividends, and drives futures pricing.","A futures price is higher than spot by an amount reflecting interest costs.","Futures price is unrelated to spot price."),
   ("Contango","Contango is a market in which futures prices are higher than the spot price, normally due to carrying costs.","The one-month future trades above spot.","Contango means futures trade below spot."),
   ("Backwardation","Backwardation is a market in which futures prices are lower than the spot price.","A future trades at a discount to the spot price.","Backwardation means futures trade above spot."),
   ("Basis","Basis is the difference between the spot price and the futures price. It narrows to zero at expiry as the two prices converge.","Spot is 24,000 and the future is 24,060; the gap shrinks as expiry nears.","Basis widens to its maximum at expiry."),
   ("Convergence","On the expiry date the futures price converges to the spot price of the underlying.","On the last day the future and spot are nearly equal.","Futures and spot are unrelated at expiry."),
   ("Mark-to-market","In futures, profit or loss is settled daily against the day's settlement price, and the amounts are debited or credited to the member accounts.","A trader's account is debited at the end of the day when prices fall.","Futures profits or losses are settled only at expiry."),
   ("Initial margin","Initial margin is the upfront deposit collected to cover the potential loss on a futures position over a short period. It is risk-based, using the SPAN system.","A trader deposits a percentage of the contract value before taking the position.","Initial margin is refunded as profit after the first day."),
   ("Exposure margin","Exposure margin is an additional margin over and above SPAN margin, collected to cover risk beyond that measured.","A buffer on top of the SPAN margin for extra safety.","Exposure margin replaces SPAN margin entirely."),
   ("SPAN","SPAN is a risk-based margining system that estimates the largest likely one-day loss across a portfolio under many scenarios.","A margin system that assesses the worst-case scenario for the entire portfolio.","SPAN charges a fixed 5% on every contract."),
   ("Square off","Squaring off means closing an open position by taking an equal and opposite position in the same contract before expiry.","A trader who bought a future sells the same contract to close the position.","Squaring off means doubling a position."),
   ("Rollover","Rolling over means closing a near-month position and opening a similar position in the next month to maintain exposure.","A trader sells the expiring contract and buys the next month's contract.","Rollover means taking physical delivery."),
   ("Hedging with index futures","A portfolio owner can sell index futures to protect against a fall in the market; the number of contracts depends on portfolio value and beta.","A fund manager sells index futures to offset a possible fall in her holdings.","Hedging requires buying index futures."),
   ("Pair trade","A pair trade buys one related security and sells another, profiting from relative price movement rather than market direction.","A trader buys a bank stock future and sells another bank's future.","A pair trade is a single long position."),
   ("Cash settlement","In cash settlement, no underlying is delivered; the difference between the contract price and the settlement price is paid in cash.","An index future ends with a rupee payment, not with shares.","Index futures settle with delivery of all 50 stocks."),
   ("Physical settlement","In physical settlement, the underlying shares are actually delivered on expiry; stock derivatives in India are physically settled.","A stock future held to expiry results in delivery of shares.","Stock futures are always cash settled."),
   ("Single-stock futures","Single stock futures are futures on individual shares, available for eligible stocks with liquidity and market-cap criteria.","A contract on a single company's share, with a fixed lot size.","Single-stock futures are available for any listed company."),
   ("Index futures","Index futures are contracts on stock indices such as the Nifty 50, are cash settled, and are widely used to hedge and speculate on the overall market.","A trader takes a view on the market as a whole with one contract.","Index futures are delivered in shares."),
   ("Long hedge versus short hedge","A short hedge sells futures to protect against price falls; a long hedge buys futures to protect against price rises.","A person expecting to buy shares next month buys futures to lock in prices.","A short hedge buys futures contracts."),
   ("Fair value of futures","The fair price of a futures contract is the spot price plus the net cost of carry; deviations create arbitrage opportunities.","A future priced well above spot plus carry attracts arbitrage sellers.","Futures can trade at any price without arbitrage."),
   ("Cash-and-carry arbitrage","Cash-and-carry arbitrage buys the underlying in the cash market and sells the future when the future is expensive relative to fair value.","A trader buys shares and sells the future, locking in a gap.","Cash-and-carry arbitrage buys futures and sells shares."),
   ("Reverse cash-and-carry","Reverse cash-and-carry sells the underlying and buys the future when the future is cheap relative to fair value.","A trader sells shares and buys a cheap future to lock in a gain.","Reverse cash-and-carry buys the underlying and sells futures."),
   ("Futures versus forwards risk","Exchange-traded futures remove counterparty risk through the clearing corporation, while forwards leave it with the counterparty.","A clearing corporation guarantees that the futures trade will be honoured.","Forward contracts are guaranteed by the exchange."),
   ("Futures margin and leverage","Because only margin is paid upfront, futures offer leverage: a small price change can produce a large percentage gain or loss on margin.","A 2% price move creates a 15% change in the trader's margin capital.","Futures margin limits the loss to the margin amount.")]),
 dict(n=4, title="Introduction to options", w=25,
  overview="Options are the second heavy unit. Calls, puts, moneyness, premium, Greeks, put-call parity and the payoff of each position.",
  focus=["Payoffs and break-even of calls and puts.", "Intrinsic value and time value.", "The Greeks.", "Settlement and exercise."],
  visuals=[("formula", "Premium", "Option premium = Intrinsic value + Time value"), ("formula", "Put-call parity (European)", "Call price − Put price = Spot − Strike ÷ (1 + r)^T")],
  facts=[("Call option buyer","The buyer of a call pays a premium and has the right to buy the underlying at the strike. Maximum loss is the premium and the potential profit is unlimited.","A trader pays ₹20 for the right to buy at ₹500 and expects a rise.","A call buyer has unlimited loss."),
   ("Call option seller","The call seller (writer) receives the premium and must sell the underlying at the strike if exercised. The maximum profit is the premium and the loss is potentially unlimited.","A trader receives ₹20 and must sell if the price rises sharply.","A call writer has unlimited profit and limited loss."),
   ("Put option buyer","The buyer of a put pays a premium and has the right to sell at the strike. Maximum loss is the premium; profit rises as the price falls to zero.","A trader pays ₹15 for the right to sell at ₹500 and expects a fall.","A put buyer benefits when the price rises."),
   ("Put option seller","The put seller receives the premium and must buy the underlying at the strike if exercised. Maximum profit is the premium; loss can be large if prices fall.","A trader receives ₹15 and must buy at ₹500 if the price collapses.","A put writer has unlimited profit."),
   ("In-the-money","A call is in the money when spot is above the strike; a put is in the money when spot is below the strike. It has positive intrinsic value.","A call with strike 500 when spot is 550.","A call is in the money when spot is below the strike."),
   ("At-the-money","An option is at the money when the strike equals the spot price. Its intrinsic value is zero.","A call with strike 500 when spot is 500.","An at-the-money option has high intrinsic value."),
   ("Out-of-the-money","A call is out of the money when spot is below the strike; a put when spot is above the strike. It has no intrinsic value, only time value.","A put with strike 500 when spot is 550.","An out-of-the-money option has the highest intrinsic value."),
   ("Intrinsic value","Intrinsic value is the amount by which an option is in the money, and is never negative. For a call it is the greater of (spot − strike) and zero.","A call with strike 500 and spot 560 has a value of ₹60 on exercise.","Intrinsic value of an option can be negative."),
   ("Time value","Time value is the part of the premium above intrinsic value, reflecting the chance of further favourable moves; it falls to zero at expiry.","An option with intrinsic value ₹60 and premium ₹75 has ₹15 of this.","Time value rises as expiry approaches."),
   ("Option premium determinants","The premium depends on spot, strike, time to expiry, volatility, interest rates and dividends; higher volatility and longer time raise it.","An option on a very volatile stock costs more than one on a stable stock.","Volatility has no effect on option premium."),
   ("Implied volatility","Implied volatility is the volatility the market's option prices imply for the underlying, derived from the option price.","Option prices suggest the market expects larger swings.","Implied volatility is the volatility in the past year."),
   ("Delta","Delta measures the change in an option's price for a ₹1 change in the underlying. Calls have delta between 0 and 1; puts between −1 and 0.","A call with delta 0.5 gains about ₹0.50 if the underlying rises ₹1.","Delta measures the effect of time decay."),
   ("Gamma","Gamma measures how much delta changes for a ₹1 move in the underlying. It is highest for at-the-money options near expiry.","The sensitivity of delta is greatest for options near the strike.","Gamma is the change in price for time decay."),
   ("Theta","Theta measures the loss in option value as one day passes, other things equal. It hurts option buyers and helps sellers.","An option loses a little value each day as expiry nears.","Theta helps option buyers."),
   ("Vega","Vega measures the change in an option's price for a 1% change in volatility. Higher volatility raises both call and put prices.","An option's price rises when volatility increases.","Vega measures the effect of interest rate changes."),
   ("Rho","Rho measures the change in an option's price for a 1% change in the interest rate.","An option's sensitivity to the interest rate.","Rho measures the effect of volatility on price."),
   ("European option","A European option can be exercised only on the expiry date. All options on Indian exchanges are European style.","A holder can exercise an option only on the last day.","A European option can be exercised any time before expiry."),
   ("American option","An American option can be exercised at any time up to and including expiry.","A holder can exercise whenever she chooses before expiry.","An American option can be exercised only at expiry."),
   ("Exercise and assignment","When a buyer exercises, a seller is assigned at random or by rule and must perform the obligation under the contract.","A call buyer exercises and a writer is called to deliver.","The option buyer is always obliged to exercise."),
   ("Settlement of index options","Index options are cash settled at expiry on the closing index value; in-the-money options are exercised automatically.","An in-the-money index option ends with a cash credit.","Index options are settled by delivering all index shares."),
   ("Settlement of stock options","Stock options are physically settled; in-the-money stock options at expiry result in delivery of shares.","A call buyer who is in the money at expiry gets shares delivered.","Stock options are always cash settled."),
   ("Put-call parity","For European options, the call price minus the put price equals the present value relationship of spot and strike; deviations offer arbitrage.","A call and put with the same strike and expiry are linked by spot and strike.","Calls and puts are priced independently."),
   ("Long call payoff","A long call's profit at expiry = max(spot − strike, 0) − premium; break-even = strike + premium.","A call with strike 500 bought at ₹20 breaks even at 520.","A long call's break-even is strike minus premium."),
   ("Long put payoff","A long put's profit at expiry = max(strike − spot, 0) − premium; break-even = strike − premium.","A put with strike 500 bought at ₹15 breaks even at 485.","A long put's break-even is strike plus premium."),
   ("Short call payoff","A short call's profit at expiry = premium − max(spot − strike, 0); break-even = strike + premium.","A writer who sold a 500 call at ₹20 starts losing above 520.","A short call is profitable at any rise in price."),
   ("Short put payoff","A short put's profit at expiry = premium − max(strike − spot, 0); break-even = strike − premium.","A writer who sold a 500 put at ₹15 loses below 485.","A short put is profitable at any fall in price."),
   ("Option writer margin","Option sellers must deposit margin because of their potential large losses; option buyers pay only the premium and need no margin.","A seller deposits margin while the buyer only pays the premium.","Option buyers must deposit margin like sellers."),
   ("Premium settlement","Premium is paid by the buyer and received by the seller on the next working day after the trade.","The premium for an option traded today is settled the following business day.","Premium is paid only at expiry."),
   ("Option chain","An option chain lists the available strikes and premiums of calls and puts for a given underlying and expiry.","A table showing calls on one side and puts on the other by strike price.","An option chain shows only futures prices."),
   ("Weekly options","Exchanges list options with weekly expiries on selected indices, subject to regulatory limits on the number of contracts.","Some index options expire every week.","All stock options expire weekly."),
   ("Early exercise of European options","Because European options cannot be exercised early, holders who want to exit before expiry sell the option in the market.","A holder sells the option in the market a week before expiry.","A European option holder may exercise any day.")]),
 dict(n=5, title="Option trading strategies", w=3,
  overview="Combining options and underlying positions shapes the risk and reward. A short unit worth three marks.",
  focus=["Covered call, protective put, spreads, straddle, strangle."],
  visuals=[("table", "Strategies at a glance", [["Strategy", "View", "Construction"], ["Covered call", "Neutral to mildly bullish", "Hold shares, sell a call"], ["Protective put", "Bullish with protection", "Hold shares, buy a put"], ["Bull call spread", "Moderately bullish", "Buy lower-strike call, sell higher-strike call"], ["Long straddle", "Big move either way", "Buy call and put at same strike"], ["Long strangle", "Big move either way, cheaper", "Buy OTM call and OTM put"]], [100, 150, 220])],
  facts=[("Covered call","A covered call holds the underlying and sells a call against it, earning the premium but capping the upside.","An investor holding shares sells a call to earn income.","A covered call has unlimited upside."),
   ("Protective put","A protective put buys a put against a held position, setting a floor under the loss at the cost of the premium.","An investor buys a put to insure shares she owns.","A protective put adds to the loss when prices fall."),
   ("Bull call spread","A bull call spread buys a lower-strike call and sells a higher-strike call, limiting both the cost and the profit.","A trader buys a 500 call and sells a 520 call.","A bull call spread has unlimited profit."),
   ("Long straddle","A long straddle buys a call and a put at the same strike and expiry, profiting from a large move in either direction.","A trader expects a big move after results but not its direction.","A long straddle profits if the price stays still."),
   ("Long strangle","A long strangle buys an out-of-the-money call and an out-of-the-money put, costing less than a straddle but needing a bigger move.","A trader buys a 520 call and a 480 put.","A long strangle uses the same strike for both options."),
   ("Collar","A collar holds the underlying, buys a put and sells a call, limiting both downside and upside, often at a low net cost.","An investor protects shares with a put financed by selling a call.","A collar leaves both ends of risk unlimited."),
   ("Bear put spread","A bear put spread buys a higher-strike put and sells a lower-strike put, profiting from a moderate fall with limited risk.","A trader buys a 500 put and sells a 480 put.","A bear put spread profits from a rise."),
   ("Butterfly spread","A butterfly spread uses three strikes to profit if the price stays near the middle strike, with limited risk and limited reward.","A trader expects little movement and uses three strikes.","A butterfly spread profits from a large move.")]),
 dict(n=6, title="Introduction to trading systems", w=4,
  overview="How orders are placed and matched in the exchange's electronic system.",
  focus=["Order types and priority.", "Trading hours.", "Position limits and bans."],
  facts=[("Order matching","Orders on the exchange are matched on price-time priority: the best price first, and among equal prices the earliest order.","Two buyers bid the same price and the earlier order is filled first.","Orders are matched on the largest size first."),
   ("Order types","Common order types are limit, market, stop loss and IOC (immediate or cancel); each controls price and timing differently.","A trader uses an order that executes immediately or is cancelled.","Only limit orders exist in the derivatives segment."),
   ("Market maker","A market maker quotes continuous two-way prices to provide liquidity in a contract.","An entity always quotes both buy and sell prices to keep the market liquid.","A market maker only buys, never sells."),
   ("Market-wide position limit","The MWPL caps the total open positions across all traders in a stock's derivatives; when it reaches 95% the stock enters a ban period.","A stock's derivative position exceeds 95% of the limit and is banned for fresh positions.","MWPL applies only to index derivatives."),
   ("Ban period","In the ban period, traders can only reduce their open positions in the stock; fresh positions are not allowed.","A trader can square off but cannot build new positions in a stock under restriction.","During a ban period all trading is banned."),
   ("Client position limit","Position limits restrict the open positions a single client or member can hold, to prevent concentration and manipulation.","A single client cannot hold unlimited open positions in one stock.","There are no limits for a single client."),
   ("Trading hours of derivatives","The equity derivatives segment trades during regular market hours, 9:15 am to 3:30 pm, on business days.","A trader places a futures order at 10 am on a working day.","Equity derivatives trade only in the pre-open session."),
   ("Price band in derivatives","Derivatives have operating ranges that stop orders far from the last price, to prevent erroneous trades.","An order far away from the market price is rejected by the system.","There is no price protection in derivatives.")]),
 dict(n=7, title="Introduction to clearing and settlement system", w=13,
  overview="After the trade comes the settlement. This unit covers clearing members, the clearing corporation, margins, daily MTM and final settlement.",
  focus=["Roles of clearing corporation and clearing members.", "Margin types and collateral.", "Settlement of futures and options."],
  visuals=[("table", "Settlement summary", [["Contract", "Daily", "At expiry"], ["Index futures", "MTM in cash", "Final settlement in cash"], ["Stock futures", "MTM in cash", "Physical delivery"], ["Index options", "Premium paid at trade", "Cash settlement of ITM"], ["Stock options", "Premium paid at trade", "Physical delivery of ITM"]], [130, 150, 190])],
  facts=[("Clearing corporation","The clearing corporation becomes the counterparty to every trade through novation, guaranteeing settlement and managing risk.","After a trade, the buyer's counterparty is the clearing entity, not the seller.","The clearing corporation sets prices of contracts."),
   ("Novation","Novation replaces the original contract between buyer and seller with two contracts, each with the clearing corporation as counterparty.","After matching, each side deals with the clearing corporation instead of the other party.","Novation cancels the trade."),
   ("Clearing member","A clearing member is authorised to clear and settle trades with the clearing corporation, for itself or for trading members.","A firm that settles trades on behalf of other brokers with the clearing corporation.","A clearing member only advises clients."),
   ("Professional clearing member","A professional clearing member clears trades for others without being a trading member itself.","An institution clears trades for several brokers but does not trade itself.","A professional clearing member is also a trading member always."),
   ("Self-clearing member","A self-clearing member is a trading member who also clears its own trades and its clients' trades.","A broker that trades and clears by itself.","A self-clearing member relies on others to settle its trades."),
   ("Daily settlement price","The daily settlement price of futures is generally the closing price (average of the last half hour), and positions are marked against it.","The price used to compute each day's profit or loss on futures.","The daily settlement price is the opening price."),
   ("Final settlement price","On expiry, the final settlement price of index futures is the closing value of the underlying index.","Index futures are settled against the index close on the last day.","The final settlement price is the previous month's average."),
   ("Settlement of premium","Option premium is settled in cash on T+1; the buyer pays and the seller receives.","The premium moves between accounts the day after the trade.","Premium is settled after expiry."),
   ("Settlement guarantee fund","The clearing corporation maintains a fund to cover member defaults, built from contributions of members and the corporation.","A pool of money used if a member fails to meet obligations.","The fund is paid to investors as dividend."),
   ("Collateral for margin","Margin can be given in cash, bank guarantees, fixed deposit receipts or approved securities, subject to haircuts.","A trader pledges approved shares instead of cash margin.","Only cash is accepted as margin."),
   ("Haircut","A haircut is a reduction applied to the value of collateral securities to protect against price falls.","A pledged share valued at ₹100 is counted at ₹80 for margin.","A haircut increases the collateral value."),
   ("Mark-to-market margin","MTM margin is collected from members for the day's losses on open positions, to ensure daily settlement.","A trader whose position fell during the day pays the difference.","MTM margin is collected only at expiry."),
   ("Peak margin","Peak margin rules require traders to maintain margin at the highest level of exposure during the day, not just at the end of the day.","A trader must hold margin for the highest exposure taken at any time in the day.","Margin is checked only at the market close."),
   ("Extreme loss margin","Extreme loss margin covers losses beyond those captured by SPAN in highly adverse moves.","A margin collected to cover extreme price moves.","Extreme loss margin is the same as premium."),
   ("Position squaring and exercise","A position can be closed by an opposite trade or held to expiry, when options are exercised or lapse and futures are settled.","A trader ends an option position by selling it before expiry.","Positions cannot be closed before expiry."),
   ("Default handling","On a member's default, the clearing corporation uses the member's margins and deposits first, then other resources, to complete settlement.","A defaulting member's deposits are used before other funds.","The investors' funds are used first for member defaults.")]),
 dict(n=8, title="Legal and regulatory environment", w=15,
  overview="Who permits derivatives, who regulates them, who is eligible to trade and what safeguards exist. Questions here test exact names and rules.",
  focus=["SCRA, SEBI Act and committees.", "Eligibility of securities and members.", "Investor protection and risk disclosure."],
  visuals=[("table", "Milestones", [["Event", "Year"], ["Derivatives permitted after the L.C. Gupta committee", "1999 amendment of SCRA"], ["Index futures launched", "June 2000"], ["Index options launched", "June 2001"], ["Stock options launched", "July 2001"], ["Stock futures launched", "November 2001"]], [320, 150])],
  facts=[("SCRA","The Securities Contracts (Regulation) Act, 1956 regulates trading in securities and, after amendment, recognises derivatives as securities.","The law that defines securities and allows derivatives trading on recognised exchanges.","The SCRA bans all derivatives trading."),
   ("SEBI Act","The SEBI Act, 1992 gives SEBI the power to regulate the securities market, including derivatives, and protect investors.","The statute that created the regulator and gave it powers.","The SEBI Act regulates only banks."),
   ("L.C. Gupta Committee","The Dr. L. C. Gupta Committee (1998) recommended the introduction of derivatives trading in India and laid out the regulatory framework.","A committee that paved the way for derivatives in India.","The committee banned derivatives in 1998."),
   ("J.R. Varma Committee","The Prof. J. R. Varma Committee recommended risk containment measures, including margining systems, for derivatives trading.","A committee whose report shaped margin and risk measures.","The Varma committee recommended banning index futures."),
   ("Eligibility of stocks","Stocks are admitted to derivatives based on criteria such as market capitalisation, free float, trading frequency and volatility.","A stock must meet liquidity and size tests to get derivatives contracts.","Any listed company can have derivatives."),
   ("Trading member","A trading member of the derivatives segment must be registered with SEBI, meet net-worth and certification norms, and have qualified dealers.","A broker must hold the NISM certificate for its dealers.","Trading members need no certification."),
   ("Certification requirement","Dealers and persons who handle derivatives business must pass the NISM derivatives certification examination.","A sales trader must hold the examination certificate to deal.","Anyone can deal in derivatives without certification."),
   ("Risk disclosure document","Brokers must give clients a risk disclosure document explaining the risks of derivatives, including leverage and the possibility of losing the entire margin.","A client must read and acknowledge the risks before trading.","A risk disclosure document is optional."),
   ("Client registration","Clients must complete KYC and sign a client-broker agreement before trading derivatives.","A new client signs the standard forms before the first trade.","A client can trade before completing KYC."),
   ("Contract note","A broker must issue a contract note for every trade, showing price, time, brokerage and charges, usually within 24 hours.","A client receives a document confirming the details of her trade.","A contract note is optional."),
   ("Segregation of client funds","Brokers must keep client funds and securities separate from their own and must not use them for proprietary trading.","A broker holds client money in a separate account.","Brokers may use client funds for their own trades."),
   ("Minimum contract size","SEBI prescribes a minimum value for a derivatives contract at the time of its introduction, reviewed periodically, so that lot sizes are meaningful.","A contract lot is set to meet the regulator's minimum value.","The exchange can fix any tiny contract value."),
   ("Suitability","Intermediaries must ensure that derivatives trading is suitable for the client given experience, income and risk appetite.","A broker checks that a retail client understands leverage before allowing trades.","Suitability is irrelevant to broking."),
   ("Prohibition of insider trading","Using unpublished price-sensitive information to trade stock derivatives is an offence under SEBI rules.","An insider buys stock futures before the company announces a merger.","Insider trading rules apply only to shares and not to derivatives."),
   ("Investor Protection Fund","Exchanges maintain a fund to compensate clients of defaulting members within prescribed limits.","A client of a failed broker receives compensation from the exchange fund.","The fund compensates every market loss."),
   ("Grievance redressal and arbitration","Disputes between clients and brokers can be taken to the exchange's arbitration, investor service cells and SEBI's complaint system.","A client files a complaint and seeks arbitration against a broker.","Clients have no recourse for disputes."),
   ("Surveillance","Exchanges and SEBI monitor derivatives markets for manipulation, with measures such as position limits and bans.","A regulator flags unusually concentrated positions.","Surveillance covers only the cash market."),
   ("Proprietary versus client trades","Brokers must distinguish their own proprietary trades from client trades and ensure they are reported and handled separately.","A broker's own account trades are tagged separately from client orders.","Proprietary and client trades are mixed together.")]),
 dict(n=9, title="Accounting and taxation", w=3,
  overview="How profits and losses from derivatives are treated for accounts and tax.",
  focus=["Income tax treatment of F&O.", "STT."],
  facts=[("Non-speculative business income","Profits or losses from index and stock futures and options are generally treated as non-speculative business income under income tax law.","A trader reports F&O profits as business income, not capital gains.","F&O gains are always taxed as capital gains."),
   ("Securities transaction tax on derivatives","STT is charged on derivatives transactions, for example on the sale of options on the premium and on futures sale, at rates set by law.","A small tax is deducted on the sell side of a futures trade.","Derivatives are exempt from all transaction taxes."),
   ("Tax audit","A person whose derivatives turnover or losses cross specified thresholds may need to get accounts audited under the tax law.","A trader with large F&O turnover must have accounts audited.","Tax audit is never required for traders."),
   ("Mark-to-market accounting","Open futures positions are marked to market at year end for accounting, and unrealised losses may be recognised.","Open positions are valued at the closing price on the balance sheet date.","Open positions are ignored at year end."),
   ("Carry forward of business losses","Non-speculative business losses from derivatives can be set off against other business income and carried forward for eight years if returns are filed on time.","A trader's F&O loss is carried forward to future years.","F&O losses can never be carried forward."),
   ("Turnover for derivatives","For tax audit purposes, turnover of futures and options is computed using specified methods, such as the absolute profit and loss and premium on sale of options.","Turnover is computed by adding absolute profits and losses for futures.","Turnover for F&O is equal to the contract value."),]),
 dict(n=10, title="Sales practices and investor protection services", w=2,
  overview="Good conduct in selling derivatives, from advice to complaints.",
  focus=["Suitability, disclosures and ethics."],
  facts=[("Know your client","Intermediaries must know the client's identity, financial position and investment objectives before allowing derivative trades.","A broker collects income and experience details from a new client.","KYC is needed only for futures and not for options."),
   ("Code of conduct","A code of conduct for brokers requires honesty, fairness, due diligence and prohibits misleading statements and unfair practices.","A broker must not promise assured profits.","Brokers can guarantee returns in derivatives."),
   ("Conflict of interest","A dealer must avoid or disclose conflicts, such as trading ahead of client orders (front running), which is prohibited.","A dealer who trades for his own account before executing a large client order commits a violation.","Front running is permitted if the client is not aware."),
   ("Complaint handling","Intermediaries must have a grievance mechanism and resolve client complaints promptly, and escalate to the exchange or SEBI if not resolved.","A client with an unresolved complaint writes to the exchange.","Clients can complain only after a year."),
   ("Appropriate advice","Dealers should explain leverage, margin calls and potential loss and avoid pushing high-risk strategies to unsuitable clients.","A dealer explains that a short option can lose more than the premium collected.","Dealers should hide risk to encourage trades.")]),
])
